"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Evidence-reliability experiment, step 2 on dev: the reliability read-out (plan summarised in docs/iterations.md,
2026-11-23; approved by the author). Exploratory: dev only, local only; no frozen file, setting or threshold changes; the
frozen training folder data/p1v4/render/train_d00 is only read.

The read-out is the main system's (step 2d: per question a logistic regression on the last-layer states at the option
positions plus the per-second ears; same holdout units, weight-decay grid and optimiser; thresholds by the plan's
operating-point rule on natural dev). Only its training data differ: labels and sound go bad independently.
  labels, per train window, half and half: "decoupled" (the step 2c edits the main system was trained on) or
          "natural" (the train split's own detector output, nearly always right);
  sound:  the R-hear and S-move train units, half kept clean, half re-rendered with the background noise louder by
          10, 20, 30 or 40 dB (one level per unit, drawn uniformly; the frozen generator and the train split's own
          noise recordings; windows in data/p1v4/render/train_rel/); every other part stays clean.
Clean windows reuse the stored train features (step 2c decoupled forward, the control's natural forward, the clean
per-second ears); only the noisy windows go through the backbone (batch 8, as the step 2c and 2d train passes).
Commands (repo root, .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_reliability_fix.py ...):
  assign    the draw (seed 20261123) -> data/p1v4/runs/reliability/fix/assign.json
  render    the noisy train windows (first a check: three units re-rendered at 0 dB must equal the stored windows)
  extract   backbone forward and per-second ears of the noisy windows, text by the window's label regime
  fit       the read-out on the mixed train set; its operating point on natural dev
  eval      dev: the step-1 grid (data/p1v4/runs/reliability/dev/), the four criteria of the plan, natural accuracy
            -> results/main_v04/reliability_step2_dev.json
"""
import copy
import json
import os
import random
import sys
import time
from types import SimpleNamespace

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402

R = "data/p1v4/runs"
FIX = f"{R}/reliability/fix"
REL_DEV = f"{R}/reliability/dev"
RENDER = os.path.join(D.RENDER, "train_rel")
SEED = 20261123
LEVELS_DB = (10, 20, 30, 40)
NOISY_PARTS = ("r_hear", "s_move")
F2C = f"{R}/grounding/allclass2c/feats_train_2c.npz"
FNAT = f"{R}/grounding/control/feats_train_natural.npz"
FSEC = f"{R}/grounding/allclass2d/sec8_train.npz"
EDITS = f"{R}/grounding/allclass2c/train_edits.json"


def _mk(d):
    os.makedirs(d, exist_ok=True)
    return d


def train_rows():
    rows = D.load_rows("train")
    return rows, D.windows_of(rows, "train")


# ------------------------------------------------------------------------------------------------ assign

def assign():
    rows, wins = train_rows()
    rng = random.Random(SEED)
    units = sorted({r["unit"] for r in rows if r["part"] in NOISY_PARTS})
    unit_db = {}
    for u in units:
        unit_db[u] = rng.choice(LEVELS_DB) if rng.random() < 0.5 else 0
    regime = {w["id"]: ("decoupled" if rng.random() < 0.5 else "natural") for w in wins}
    out = {"seed": SEED, "unit_db": unit_db, "regime": regime}
    json.dump(out, open(os.path.join(_mk(FIX), "assign.json"), "w"))
    n_noisy = sum(v > 0 for v in unit_db.values())
    by_db = {d: sum(v == d for v in unit_db.values()) for d in (0,) + LEVELS_DB}
    win_noisy = sum(1 for w in wins if unit_db.get(w["unit"], 0) > 0)
    print(f"R-hear and S-move train units {len(units)}, noisy {n_noisy}, by dB {by_db}; noisy windows {win_noisy}; "
          f"regimes {sum(v == 'decoupled' for v in regime.values())} decoupled of {len(regime)}", flush=True)


def load_assign():
    return json.load(open(os.path.join(FIX, "assign.json")))


# ------------------------------------------------------------------------------------------------ render

def render():
    import soundfile as sf
    import p1v4_units as U
    a = load_assign()
    rows, _ = train_rows()
    by = {}
    for r in rows:
        if r["part"] in NOISY_PARTS:
            by.setdefault(r["unit"], []).append(r)
    A = U.Assets("train")
    _mk(RENDER)

    def one(u, db, write):
        rs = by[u]
        spec = copy.deepcopy(rs[0]["spec"])
        spec["snr_db"] = round(spec["snr_db"] - db, 2)
        tls = {r["version"]: SimpleNamespace(src=r["sources"], points=r["points"], assistant=r["assistant"])
               for r in rs}
        audio, gain_db = U.render_versions(spec, tls, A)
        out = {}
        for r in rs:
            for p in r["points"]:
                w = U.windows(audio[r["version"]], [p])[0]
                assert len(w) == int(D.WIN_S * D.SR)
                wid = f"{u}|{r['version']}|{p['k']}"
                if write:
                    path = os.path.join(RENDER, f"{u}_{r['version']}_p{p['k']}.wav").replace("\\", "/")
                    sf.write(path, w, U.SR, subtype="PCM_16")
                    out[wid] = {"path": path, "db": db, "gain_db": gain_db}
                else:
                    out[wid] = (w, p["window"])
        return out

    # check: re-rendered at 0 dB, three units equal the stored train windows
    check = {}
    for u in sorted(by)[:3]:
        for wid, (w, path) in one(u, 0, False).items():
            ref = sf.read(path, dtype="int16")[0]
            got = np.round(np.asarray(w, dtype=np.float64)).astype(np.int64) if np.asarray(w).dtype.kind != "f" \
                else np.round(np.asarray(w) * (32767 if np.abs(w).max() <= 1.0 else 1)).astype(np.int64)
            check[wid] = int(np.abs(got - ref.astype(np.int64)).max())
    json.dump(check, open(os.path.join(FIX, "render_check.json"), "w"), indent=1)
    worst = max(check.values())
    print(f"render check: {len(check)} windows, max |sample difference| {worst}", flush=True)
    if worst > 1:
        raise SystemExit("re-rendering at 0 dB does not reproduce the stored train windows")
    meta, t0 = {}, time.time()
    noisy = sorted(u for u, db in a["unit_db"].items() if db > 0)
    for i, u in enumerate(noisy):
        meta.update(one(u, a["unit_db"][u], True))
        if i % 500 == 0:
            print(f"rendered {i + 1}/{len(noisy)} units, {time.time() - t0:.0f} s", flush=True)
    json.dump(meta, open(os.path.join(FIX, "noisy_windows.json"), "w"))
    print(f"render done: {len(noisy)} units, {len(meta)} windows, {time.time() - t0:.0f} s", flush=True)


# ------------------------------------------------------------------------------------------------ extract

def extract():
    import soundfile as sf
    import torch
    import p1v4_l1 as L1
    import p1v4_readout as RO
    import p1v4_readout_allclass as AC
    from p1v4_readout_2d import per_second
    D.gpu_guard()
    a = load_assign()
    noisy = json.load(open(os.path.join(FIX, "noisy_windows.json")))
    rows, wins = train_rows()
    rows_by = {(r["unit"], r["version"]): r for r in rows}
    edits = {k: [tuple(e) for e in v] for k, v in json.load(open(EDITS)).items()}
    ctx = {"decoupled": AC.MultiEdited("train", edits), "natural": C.Context("train")}
    model = L1.build()
    L1.load_new_state(model, torch.load(f"{R}/l1/l1_new.pt", weights_only=True))
    model.eval()
    items = []
    for w in wins:
        if w["id"] not in noisy:
            continue
        reg = a["regime"][w["id"]]
        text, asks = ctx[reg].situation(rows_by[w["key"]], w["k"], "full")
        qs = [q for q in ("S", "R") if any(x.startswith(q + ":") for x in asks)]
        items.append({"id": w["id"], "unit": w["unit"], "path": noisy[w["id"]]["path"], "text": text,
                      "marker": "agent" if w["assistant_speaking"] else "user", "qs": qs, "regime": reg,
                      "db": noisy[w["id"]]["db"]})
    H, SM, SX, QW, QT = [], [], [], [], []
    t0, B = time.time(), 8
    for i in range(0, len(items), B):
        chunk = items[i:i + B]
        waves = torch.stack([torch.from_numpy(sf.read(it["path"], dtype="float32")[0]) for it in chunk]).cuda()
        h, _, qw, _ = RO.forward_states(model, waves, [it["text"] for it in chunk], [it["marker"] for it in chunk],
                                        [[RO.TASK[q] for q in it["qs"]] for it in chunk])
        sm, sx, _ = per_second(model.vt, waves)
        H.append(h.astype(np.float16))
        SM.append(sm.astype(np.float16))
        SX.append(sx.astype(np.float16))
        QW.append(qw + i)
        QT += [q for it in chunk for q in it["qs"]]
        if (i // B) % 300 == 0:
            print(f"noisy train: {i + len(chunk)}/{len(items)} windows {time.time() - t0:.0f} s", flush=True)
    np.savez(os.path.join(FIX, "feats_train_noisy.npz"), states=np.concatenate(H), sec_mean=np.concatenate(SM),
             sec_max=np.concatenate(SX), q_win=np.concatenate(QW), q_task=np.array(QT),
             ids=np.array([it["id"] for it in items]), regime=np.array([it["regime"] for it in items]),
             db=np.array([it["db"] for it in items]))
    print(f"noisy train done: {len(items)} windows, {len(QT)} questions, {time.time() - t0:.0f} s", flush=True)


# ------------------------------------------------------------------------------------------------ fit

def mixed_train():
    """States per question and per-second ears per window of the mixed train set, in the step 2c file's order."""
    a = load_assign()
    z = dict(np.load(F2C))
    zn = np.load(FNAT)
    e = dict(np.load(FSEC))
    assert np.array_equal(z["ids"], zn["ids"]) and np.array_equal(z["ids"], e["ids"])
    for k in ("q_win", "q_task", "q_gold"):
        assert np.array_equal(z[k], zn[k]), k
    states = z["states"]
    nat_states = zn["states"]
    pos = {i: n for n, i in enumerate(z["ids"])}
    qidx = {}
    for j, (w, q) in enumerate(zip(z["q_win"], z["q_task"])):
        qidx[(int(w), str(q))] = j
    noisy_ids = set()
    zz = dict(np.load(os.path.join(FIX, "feats_train_noisy.npz")))
    for n, wid in enumerate(zz["ids"]):
        noisy_ids.add(str(wid))
        g = pos[str(wid)]
        e["sec_mean"][g] = zz["sec_mean"][n]
        e["sec_max"][g] = zz["sec_max"][n]
    for j, (w, q) in enumerate(zip(zz["q_win"], zz["q_task"])):
        states[qidx[(pos[str(zz["ids"][int(w)])], str(q))]] = zz["states"][j]
    counts = {"clean decoupled": 0, "clean natural": 0, "noisy decoupled": 0, "noisy natural": 0}
    for wid, g in pos.items():
        reg = a["regime"][wid]
        if wid in noisy_ids:
            counts[f"noisy {reg}"] += 1
            continue
        counts[f"clean {reg}"] += 1
    nat_q = np.array([a["regime"][str(z["ids"][int(w)])] == "natural" and str(z["ids"][int(w)]) not in noisy_ids
                      for w in z["q_win"]])
    states[nat_q] = nat_states[nat_q]
    return z, states, e["sec_mean"], e["sec_max"], counts


def fit():
    import p1v4_readout as RO
    import p1v4_readout_2d as R2D
    import p1v4_score as S
    D.gpu_guard()
    z, states, sm_all, sx_all, counts = mixed_train()
    print("train windows:", counts, flush=True)
    units = z["units"][z["q_win"]]
    rng = np.random.default_rng(RO.SEED)                    # the same holdout units as the 2c and 2d fits
    uniq = np.unique(z["units"])
    hold_units = set(rng.choice(uniq, size=len(uniq) // 5, replace=False))
    hold = np.array([u in hold_units for u in units])
    log, models = {"counts": counts}, {}
    for q in ("S", "R"):
        m = np.where((z["q_task"] == q) & (z["q_gold"] >= 0))[0]
        wq = z["q_win"][m]
        X = R2D.design(states[m], sm_all[wq], sx_all[wq])
        mu, sd = X.mean(0), X.std(0) + 1e-6
        X -= mu
        X /= sd
        Xh = X.astype(np.float16)
        del X
        y = z["q_gold"][m]
        hm = hold[m]
        best = None
        for wd in RO.WDS:
            lin = RO.train_logreg(Xh[~hm], y[~hm], wd)
            p = np.clip(RO.predict(lin, Xh[hm]), 1e-7, 1 - 1e-7)
            yy = y[hm]
            ll = float(-np.mean(yy * np.log(p) + (1 - yy) * np.log(1 - p)))
            log[f"rel {q} wd {wd}"] = ll
            print(f"reliability {q} wd {wd}: holdout log loss {ll:.4f}", flush=True)
            if best is None or ll < best[0]:
                best = (ll, wd)
        lin = RO.train_logreg(Xh, y, best[1])
        models[q] = {"mu": mu, "sd": sd, "w": lin.weight.detach().cpu().numpy()[0],
                     "b": float(lin.bias.detach().cpu().numpy()[0]), "wd": best[1]}
        del Xh
    np.savez(os.path.join(FIX, "readouts_rel.npz"),
             **{f"ears8|{q}|{f}": v for q, d in models.items() for f, v in d.items()})
    # operating point on natural dev (the plan's rule), as every system
    rows = D.load_rows("dev")
    zn = dict(np.load(f"{RO.OUT}/feats_dev_natural.npz"))
    sc = R2D.scores_2d(zn, R2D.Sec(), load_rel())
    op = S.operating_point(rows, sc)
    log["operating_point"] = {k: op[k] for k in ("th_s", "th_r", "floors_met", "primary", "lowest_floor")}
    json.dump(log, open(os.path.join(FIX, "fit_log.json"), "w"), indent=1, default=float)
    print("fitted:", {q: d["wd"] for q, d in models.items()}, "operating point:", log["operating_point"], flush=True)


def load_rel():
    z = np.load(os.path.join(FIX, "readouts_rel.npz"))
    out = {}
    for k in z.files:
        _, q, f = k.split("|")
        out.setdefault(q, {})[f] = z[k]
    return out


# ------------------------------------------------------------------------------------------------ eval

def eval_():
    import collections
    import p1v4_readout as RO
    import p1v4_readout_2d as R2D
    import p1v4_reliability_dev as RD
    import p1v4_score as S
    import p1v4_step0_confidence as S0
    st = RD.rehearsal_settings()
    op = json.load(open(os.path.join(FIX, "fit_log.json")))["operating_point"]
    th = {"2d": (st["main"]["th_s"], st["main"]["th_r"]),
          "old head": (st["local"]["L1"]["th_s"], st["local"]["L1"]["th_r"]),
          "reliability": (op["th_s"], op["th_r"])}
    ro2d, rorel = R2D.load_2d(), load_rel()

    def scores(z):
        sec = R2D.Sec(None, z["ids"], z["sec_mean"], z["sec_max"])
        return {"2d": RD.keyed(R2D.scores_2d(z, sec, ro2d)), "old head": RD.keyed(RO.scores_of(z, None, None)),
                "reliability": RD.keyed(R2D.scores_2d(z, sec, rorel))}
    res = {"split": "dev", "note": "exploratory (evidence-reliability step 2); plan docs/p1_v04_reliability_step2_plan.md",
           "thresholds": th, "train_counts": json.load(open(os.path.join(FIX, "fit_log.json")))["counts"],
           "cells": {}, "groups_all_right": {}, "natural": {}, "criteria": {}}
    for lv in RD.LEVELS:
        for cond in RD.CONDS:
            z = dict(np.load(f"{REL_DEV}/{lv}/l1_{cond}.npz"))
            sc = scores(z)
            for n in th:
                qs = RD.questions(z, sc[n], th[n])
                for part in ("r_hear", "s_move"):
                    sel = [x for x in qs if x[1] == part]
                    if not sel:
                        continue
                    res["cells"].setdefault(part, {}).setdefault(cond, {}).setdefault(n, {})[lv] = \
                        S0.summary([x[4] for x in sel], [x[5] for x in sel])
                    ok = collections.defaultdict(lambda: True)
                    for x in sel:
                        ok[x[0]] = ok[x[0]] and bool(x[5])
                    res["groups_all_right"].setdefault(part, {}).setdefault(cond, {}).setdefault(n, {})[lv] = \
                        float(np.mean(list(ok.values())))
    # natural dev: five-part mean at each system's thresholds
    rows = D.load_rows("dev")
    gmap = S.load_groups("dev")
    zn = dict(np.load(f"{RO.OUT}/feats_dev_natural.npz"))
    sec = R2D.Sec()
    for n, ro in (("2d", ro2d), ("reliability", rorel)):
        sc = R2D.scores_2d(zn, sec, ro)
        m = S.metrics(S.unit_table(rows, S.decide(sc, *th[n]), gmap))
        res["natural"][n] = {"primary": m["primary"], "parts": m["parts"], "floors": m["floors"]}
    C_ = res["cells"]
    G_ = res["groups_all_right"]
    crit = {}
    c1 = {}
    for part in ("r_hear", "s_move"):
        for lv in ("dnoise20", "dnoise30", "dnoise40"):
            new, old = C_[part]["truth"]["reliability"][lv]["accuracy"], C_[part]["truth"]["old head"][lv]["accuracy"]
            c1[f"{part} {lv}"] = {"reliability": new, "old head": old, "gap": new - old, "pass": new >= old - 0.05}
    crit["1 truth labels, bad ears: within 5 points of the old head"] = {"cells": c1,
                                                                        "pass": all(v["pass"] for v in c1.values())}
    c2 = {}
    for part in ("r_hear", "s_move"):
        for lv in ("dnoise30", "dnoise40"):
            x = C_[part]["none"]["reliability"][lv]
            ce, cs = x["confident_error_rate"], x["confident_share"]
            c2[f"{part} {lv}"] = {"confident_error_rate": ce, "confident_share": cs,
                                  "main system": C_[part]["none"]["2d"][lv]["confident_error_rate"],
                                  "pass": ce is not None and ce <= 0.10 and cs >= 0.25}
    crit["2 no labels, bad ears: confident errors <= 10% and confident share >= 25%"] = {
        "cells": c2, "pass": all(v["pass"] for v in c2.values())}
    c3 = {}
    for part, cond in (("r_hear", "c0.99"), ("s_move", "mv0.99")):
        new, main = G_[part][cond]["reliability"]["dclean"], G_[part][cond]["2d"]["dclean"]
        c3[part] = {"reliability": new, "main system": main, "gap": new - main, "pass": new >= main - 0.05}
    crit["3 fake labels, clean ears: group all-right within 5 points of the main system"] = {
        "cells": c3, "pass": all(v["pass"] for v in c3.values())}
    nn, nm = res["natural"]["reliability"]["primary"], res["natural"]["2d"]["primary"]
    crit["4 natural dev five-part mean within 3 points of the main system"] = {
        "reliability": nn, "main system": nm, "gap": nn - nm, "pass": nn >= nm - 0.03}
    res["criteria"] = crit
    os.makedirs("results/main_v04", exist_ok=True)
    json.dump(res, open("results/main_v04/reliability_step2_dev.json", "w"), indent=1, default=float)
    print("thresholds:", json.dumps(th), "train windows:", json.dumps(res["train_counts"]))
    for k, v in crit.items():
        print(f"CRITERION {k}: {'PASS' if v['pass'] else 'FAIL'}")
        cells = v.get("cells")
        if cells:
            for ck, cv in cells.items():
                print("   ", ck, json.dumps({a: (round(b, 3) if isinstance(b, float) else b) for a, b in cv.items()}))
        else:
            print("   ", json.dumps({a: (round(b, 3) if isinstance(b, float) else b) for a, b in v.items()}))
    for part, cs in C_.items():
        for cond, ns in cs.items():
            print(f"== {part} / {cond}: accuracy | group all-right | mean confidence | confident share | "
                  f"confident errors")
            for n, lvs in ns.items():
                cells = []
                for lv, x in lvs.items():
                    ce = "n/a" if x["confident_error_rate"] is None else f"{x['confident_error_rate']:.3f}"
                    cells.append(f"{lv[1:]}: {x['accuracy']:.3f} {G_[part][cond][n][lv]:.3f} {x['mean_conf']:.3f} "
                                 f"{x['confident_share']:.3f} {ce}")
                print(f"  {n:12s} " + " | ".join(cells))
    print("-> results/main_v04/reliability_step2_dev.json")


if __name__ == "__main__":
    cmd = sys.argv[1] if len(sys.argv) > 1 else ""
    {"assign": assign, "render": render, "extract": extract, "fit": fit, "eval": eval_}.get(
        cmd, lambda: (_ for _ in ()).throw(SystemExit(__doc__)))()
